<?php
declare(strict_types=1);
require_once __DIR__.'/suppliers.php';
function config_path(): string { return dirname(__DIR__).'/.private/config.php'; }
function config(): array { static $c; if(!$c){ if(!is_file(config_path()))throw new RuntimeException('SETUP_REQUIRED'); $c=require config_path(); } return $c; }
function db(): PDO { static $db; if(!$db){$c=config();$db=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);} return $db; }
function sql(string $query,array $args=[]): PDOStatement { $s=db()->prepare($query);$s->execute($args);return $s; }
function json_response(mixed $data,int $status=200): never { http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit; }
function body(): array { $raw=file_get_contents('php://input',false,null,0,32769);if(strlen($raw)>32768)json_response(['error'=>'Corpo muito grande'],413);$data=json_decode($raw,true,32,JSON_THROW_ON_ERROR);if(!is_array($data))throw new RuntimeException('INVALID_INPUT');return $data; }
function session_boot(): void { if(session_status()===PHP_SESSION_ACTIVE)return;ini_set('session.use_strict_mode','1');session_name('smartdrop_session');$secure=is_file(config_path())?str_starts_with(config()['app_url'],'https://'):(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax','path'=>'/']);session_start();if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32)); }
function origin_allowed(): bool { $origin=$_SERVER['HTTP_ORIGIN']??'';if(is_file(config_path()))return hash_equals(config()['app_url'],$origin);$host=$_SERVER['HTTP_HOST']??'';$parts=parse_url($origin);return isset($parts['host'])&&strtolower(($parts['host']).(isset($parts['port'])?':'.$parts['port']:''))===strtolower($host)&&in_array($parts['scheme']??'',['http','https'],true); }
function csrf(): void { if(!origin_allowed() || !hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??''))json_response(['error'=>'Origem ou sessão inválida. Recarregue a página.'],403); }
function admin(): void { if(empty($_SESSION['admin']) || ($_SESSION['expires']??0)<time())json_response(['error'=>'Autenticação necessária'],401); }
function setting(string $name,string $default=''): string { $s=sql('SELECT value FROM settings WHERE name=?',[$name])->fetchColumn();return $s===false?$default:(string)$s; }
function set_setting(string $name,string $value): void { sql('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$name,$value]); }
function simulation(): bool {return setting('mode','simulation')!=='live';}
function audit(string $action,?string $id=null,string $outcome='success',string $actor='admin'): void {sql('INSERT INTO audit_logs(actor,action,entity_id,outcome) VALUES(?,?,?,?)',[$actor,$action,$id,$outcome]);}
function encrypt_value(array $value): string { $key=base64_decode(config()['encryption_key'],true);if(strlen($key)!==32)throw new RuntimeException('INVALID_KEY');$iv=random_bytes(12);$cipher=openssl_encrypt(json_encode($value,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new RuntimeException('ENCRYPT_FAILED');return base64_encode($iv.$tag.$cipher); }
function decrypt_value(string $value): array {$raw=base64_decode($value,true);if($raw===false||strlen($raw)<29)throw new RuntimeException('INVALID_CIPHER');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',base64_decode(config()['encryption_key'],true),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));if($plain===false)throw new RuntimeException('DECRYPT_FAILED');return json_decode($plain,true,32,JSON_THROW_ON_ERROR);}
function transaction(callable $fn): mixed {db()->beginTransaction();try{$result=$fn();db()->commit();return $result;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
function seed(): void {foreach((new MockSupplierAdapter)->getProducts() as $p)sql('INSERT IGNORE INTO products(sku,supplier_sku,title,image,cost,stock) VALUES(?,?,?,?,?,?)',[$p['sku'],$p['sku'],$p['title'],$p['image'],$p['cost'],$p['stock']]);$ids=['2000010847291','2000010847256','2000010847208','2000010847194','2000010847142'];$values=[15990,18990,9990,6990,7990];foreach($ids as $i=>$id){sql("INSERT IGNORE INTO orders(id,status,total,payment_confirmed,simulated) VALUES(?,'awaiting_approval',?,1,1)",[$id,$values[$i]]);$sku='MDB-00'.($i+1);sql('INSERT IGNORE INTO order_lines(order_id,sku,quantity,unit_cost) VALUES(?,?,1,?)',[$id,$sku,(new MockSupplierAdapter)->getPrice($sku)]);}}
function prepare_order(string $id): array { if(!simulation())throw new RuntimeException('Compras reais bloqueadas até validação do fornecedor');return transaction(function()use($id){$o=sql('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$o||!$o['simulated'])throw new RuntimeException('Pedido não elegível');if($o['supplier_order_id'])return ['id'=>$o['supplier_order_id'],'simulated'=>true,'duplicate'=>true];if(!$o['payment_confirmed'])throw new RuntimeException('Pagamento não confirmado');if(!$o['manual_approved']||!$o['logistics_validated']||!$o['fiscal_validated'])throw new RuntimeException('Aprovação e validação logística/fiscal obrigatórias');$lines=sql('SELECT p.supplier_sku,l.quantity FROM order_lines l JOIN products p ON p.sku=l.sku WHERE l.order_id=?',[$id])->fetchAll(PDO::FETCH_ASSOC);$items=array_map(fn($l)=>['sku'=>$l['supplier_sku'],'quantity'=>(int)$l['quantity']],$lines);$result=(new MockSupplierAdapter)->createOrder(['idempotencyKey'=>$id,'items'=>$items]);sql("UPDATE orders SET supplier_order_id=?,status='simulated' WHERE id=?",[$result['id'],$id]);sql("INSERT INTO order_events(order_id,event) VALUES(?,'supplier.simulated')",[$id]);audit('order.simulate',$id);return $result;});}
